#!/usr/bin/env bash
set -euo pipefail; source "$(dirname "$0")/lib.sh"; [[ $# == 1 ]] || die 'usage: rollback.sh TARGET_SHA'; sha="$1"; require_sha "$sha"; api="$DX_ROOT/releases/$sha"; web="$DX_ROOT/frontend/releases/$sha"; assert_release "$api" "$sha"; assert_release "$web" "$sha"; schema="$(manifest_field "$api/release-manifest.json" schemaVersion)"; [[ "$schema" == "${DX_REWORK_CURRENT_SCHEMA:?current schema required}" ]] || die 'rollback schema incompatible'; before="$(readlink -f "$DX_ROOT/current"||true)"; DX_REWORK_MIGRATION_HISTORY_OK=true "$(dirname "$0")/activate-release.sh" "$sha"; "$(dirname "$0")/smoke.sh" "$sha" "$schema" || die 'rollback smoke failed'; safe_log pass "rollback before=$before after=$sha"
